  "school": {
    "classes": [
      {
        "class_id": "art",
        "students": [
          {
            "student_id": "s1",
            "grade": 70,
            "present": true
          },
          {
            "student_id": "s2",
            "grade": 80,
            "present": false
          }
        ]
      },
      {
        "class_id": "math",
        "students": [
          {
            "student_id": "s1",
            "grade": 85,
            "present": true
          },
          {
            "student_id": "s3",
            "grade": 90,
            "present": true
          }
        ]
      }
    ],
    "name": "Oak"
  }
}

Task:
